def solve(n: int) -> str:
    if n % 15 == 0:
        return "FizzBuzz"
    if n % 3 == 0:
        return "Fizz"
    if n % 5 == 0:
        return "Buzz"
    return str(n)

def solve(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    divisor = 3
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 2
    return True

def solve(items: list) -> list:
    result = items[:]
    for i in range(0, len(result) - 1, 2):
        result[i], result[i + 1] = result[i + 1], result[i]
    return result

def solve(a: list, b: list) -> list:
    result = []
    for i in range(max(len(a), len(b))):
        if i < len(a):
            result.append(a[i])
        if i < len(b):
            result.append(b[i])
    return result

def solve(n: int, width: int) -> str:
    value = str(n)
    return "0" * max(0, width - len(value)) + value

def solve(s: str) -> int:
    words = s.split()
    return len(words[-1]) if words else 0

def solve(word: str) -> str:
    if len(word) <= 3:
        return word
    return word[0] + str(len(word) - 2) + word[-1]

def solve(n: int) -> int:
    a, b = 0, 1
    for bit in bin(n)[2:]:
        c = a * (2 * b - a)
        d = a * a + b * b
        if bit == "0":
            a, b = c, d
        else:
            a, b = d, c + d
    return a

def solve(words: list) -> str:
    if not words:
        return ""
    if len(words) == 1:
        return words[0]
    return ", ".join(words[:-1]) + " and " + words[-1]

def solve(n: int) -> int:
    count = 0
    while n:
        n &= n - 1
        count += 1
    return count
